import Joi from 'joi'

const DOB_KEYS = ['dob-day', 'dob-month', 'dob-year']

const registrationRoutes = [
  {
    method: 'GET',
    path: '/register/name',
    handler: (_request, h) => {
      return h.view('registration/name', {
        pageTitle: 'What is your full name?'
      })
    }
  },
  {
    method: 'POST',
    path: '/register/name',
    options: {
      validate: {
        payload: Joi.object({
          fullName: Joi.string().trim().required().messages({
            'string.empty': 'Enter your full name',
            'any.required': 'Enter your full name'
          }),
          'dob-day': Joi.number().integer().min(1).max(31).required().messages({
            'number.base': 'Date of birth must include a day',
            'number.integer': 'Enter a real date of birth',
            'number.min': 'Enter a real date of birth',
            'number.max': 'Enter a real date of birth',
            'any.required': 'Date of birth must include a day'
          }),
          'dob-month': Joi.number().integer().min(1).max(12).required().messages({
            'number.base': 'Date of birth must include a month',
            'number.integer': 'Enter a real date of birth',
            'number.min': 'Enter a real date of birth',
            'number.max': 'Enter a real date of birth',
            'any.required': 'Date of birth must include a month'
          }),
          'dob-year': Joi.number().integer().min(1900).max(2100).required().messages({
            'number.base': 'Date of birth must include a year',
            'number.integer': 'Enter a real date of birth',
            'number.min': 'Enter a real date of birth',
            'number.max': 'Enter a real date of birth',
            'any.required': 'Date of birth must include a year'
          }),
          crumb: Joi.string()
        }),
        failAction: (request, h, error) => {
          const fieldErrors = Object.fromEntries(
            error.details.map((d) => [d.context.key, { text: d.message }])
          )

          const dobErrors = error.details.filter((d) => DOB_KEYS.includes(d.context.key))
          if (dobErrors.length > 0) {
            fieldErrors.dob = { text: dobErrors[0].message }
          }

          const nonDobErrors = error.details.filter((d) => !DOB_KEYS.includes(d.context.key))
          const errorSummary = [
            ...nonDobErrors.map((d) => ({ text: d.message, href: `#${d.context.key}` })),
            ...(dobErrors.length > 0 ? [{ text: dobErrors[0].message, href: '#dob-day' }] : [])
          ]

          return h.view('registration/name', {
            pageTitle: 'Error: What is your full name?',
            errorSummary,
            errors: fieldErrors,
            payload: request.payload
          }).takeover()
        }
      }
    },
    handler: (_request, h) => {
      return h.redirect('/register/email')
    }
  }
]

