import Joi from 'joi'

const fullNameSchema = Joi.object({
  fullName: Joi.string().trim().required().messages({
    'string.empty': 'Enter your full name',
    'any.required': 'Enter your full name'
  })
}).unknown(true)

function mapValidationErrors (error) {
  const errorList = []
  const fieldErrors = {}
  for (const detail of error.details) {
    const field = String(detail.path[0])
    const text = detail.message
    if (!fieldErrors[field]) {
      errorList.push({ text, href: `#${field}` })
      fieldErrors[field] = { text }
    }
  }
  return { errorList, fieldErrors }
}

const registrationRoutes = [
  {
    method: 'GET',
    path: '/register/name',
    handler: (_request, h) => {
      return h.view('registration/name', {
        pageTitle: 'What is your full name?',
        errorList: [],
        fieldErrors: {},
        values: {}
      })
    }
  },
  {
    method: 'POST',
    path: '/register/name',
    handler: async (request, h) => {
      const { error } = fullNameSchema.validate(request.payload, {
        abortEarly: false
      })

      if (error) {
        const { errorList, fieldErrors } = mapValidationErrors(error)
        return h.view('registration/name', {
          pageTitle: 'Error: What is your full name?',
          errorList,
          fieldErrors,
          values: { fullName: request.payload?.fullName }
        })
      }

      return h.redirect('/register/email')
    }
  }
]

